import { createClient } from '@oneplatform/app-sdk';

const client = createClient();

async function renderDashboard() {
  const container = document.getElementById('app');
  container.innerHTML = '<h1>Acme Admin Dashboard</h1><p>Loading data...</p>';

  try {
    const customers = await client.data.entity('Customer').list({ limit: 10 });
    const orders = await client.data.entity('Order').list({ limit: 10 });

    let html = '<h1>Acme Admin Dashboard</h1>';
    html += '<section><h2>Recent Customers</h2><table>';
    html += '<tr><th>Company</th><th>Industry</th><th>Status</th><th>Revenue</th></tr>';
    for await (const page of customers) {
      for (const c of page.items) {
        html += `<tr><td>${c.companyName}</td><td>${c.industry || '-'}</td>`;
        html += `<td>${c.status}</td><td>$${(c.annualRevenue || 0).toLocaleString()}</td></tr>`;
      }
    }
    html += '</table></section>';

    html += '<section><h2>Recent Orders</h2><table>';
    html += '<tr><th>Order ID</th><th>Amount</th><th>Status</th><th>Date</th></tr>';
    for await (const page of orders) {
      for (const o of page.items) {
        html += `<tr><td>${o.orderId}</td><td>$${o.totalAmount.toFixed(2)}</td>`;
        html += `<td>${o.status}</td><td>${new Date(o.orderedAt).toLocaleDateString()}</td></tr>`;
      }
    }
    html += '</table></section>';

    container.innerHTML = html;
  } catch (err) {
    container.innerHTML = `<h1>Error</h1><pre>${err.message}</pre>`;
  }
}

renderDashboard();

