import { createClient } from '@oneplatform/app-sdk';

const client = createClient();

async function renderPortal() {
  const container = document.getElementById('app');
  container.innerHTML = '<p class="loading">Loading your activity...</p>';

  try {
    const events = await client.data.entity('Event').list({ limit: 20 });

    let html = '<h1>Your Recent Activity</h1>';
    html += '<div class="event-list">';

    for await (const page of events) {
      for (const evt of page.items) {
        const icon = evt.eventType === 'purchase' ? '\uD83D\uDED2' :
                     evt.eventType === 'refund' ? '\u21A9\uFE0F' :
                     evt.eventType === 'page_view' ? '\uD83D\uDC41' : '\u26A1';
        html += `<div class="event-card">`;
        html += `<span class="event-icon">${icon}</span>`;
        html += `<div class="event-detail">`;
        html += `<strong>${evt.eventType.replace(/_/g, ' ')}</strong>`;
        html += `<span class="event-time">${new Date(evt.occurredAt).toLocaleString()}</span>`;
        html += `<span class="event-source">via ${evt.source}</span>`;
        html += `</div></div>`;
      }
    }

    html += '</div>';
    container.innerHTML = html;
  } catch (err) {
    container.innerHTML = `<div class="error"><h2>Something went wrong</h2><p>${err.message}</p></div>`;
  }
}

renderPortal();

